package com.creditsense.security;
import com.creditsense.repo.Repositories; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.context.annotation.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.SecurityFilterChain; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter; import org.springframework.web.filter.OncePerRequestFilter; import org.springframework.stereotype.Component; import java.io.IOException; import java.util.List;
@Configuration @EnableMethodSecurity public class SecurityConfig { private final JwtFilter jwt; public SecurityConfig(JwtFilter jwt){this.jwt=jwt;} @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();} @Bean SecurityFilterChain chain(HttpSecurity h)throws Exception{return h.csrf(c->c.disable()).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/api/auth/**","/swagger-ui/**","/v3/api-docs/**","/actuator/**").permitAll().anyRequest().authenticated()).addFilterBefore(jwt,UsernamePasswordAuthenticationFilter.class).build();}}
@Component class JwtFilter extends OncePerRequestFilter { private final JwtService tokens; private final Repositories.Users users; JwtFilter(JwtService tokens, Repositories.Users users){this.tokens=tokens;this.users=users;} @Override protected boolean shouldNotFilter(HttpServletRequest r){return r.getRequestURI().startsWith("/api/auth")||r.getRequestURI().startsWith("/swagger")||r.getRequestURI().startsWith("/v3/");} @Override protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException{String h=r.getHeader("Authorization"); if(h!=null&&h.startsWith("Bearer "))try{var u=users.findById(tokens.subject(h.substring(7))).orElseThrow();var a=List.of(new SimpleGrantedAuthority("ROLE_"+u.getRole().name())); SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(u.getId(),null,a));}catch(Exception ignored){} c.doFilter(r,s);}}
